--- a/packages/editor/src/core/project-io.ts
+++ b/packages/editor/src/core/project-io.ts
@@ -1 +1 @@
 /**
  * 项目 IO(D-B1 布置模式 · 逻辑层 L3)。
  *
  * 读入(LoadedProject → EditorState)与序列化(EditorState → 可落盘 JSON 文件集)。
  * 当前编辑器按契约调用:
  *   - toEditorState:把 loader 读入的项目(by-id Record)翻成编辑器工作副本(数组,对齐 JSON 文件)。
  *   - serializeProject:把工作副本序列化成 {相对路径: JSON 值} 的文件集(含 manifest.json)。
  *   - writeProject:完整暂存、校验和可恢复提交的唯一作者保存入口。
  *
  * round-trip 是命脉:toEditorState → serializeProject 必须还原原 content JSON(by-id Record
  * 经 Object.values 还原数组,保持原序)。测钉死。
  *
  * 见 docs/phase2/archive/plans/editor-b1-logic-plan.md(契约 + L3)。
  */

 import {
   type AssetCatalogV1,
   type AuthorSceneDef,
   type AuthorScriptLibrary,
   checkAuthorScriptLibrary,
   formatProjectMap,
   formatStampTemplates,
   type ProjectMap,
   type RuntimeSceneDef,
   type SceneDef,
   type SceneIndexV1,
   type ScriptChunkV1,
   type StampTemplate,
   validateAssetCatalog,
   validateMapIndex,
   validateSceneIndex,
   validateShops,
   validateWorldVariableRegistryV1,
 } from '@type-pal/content'
 import {
   decodeBattleSpriteAssetBytes,
   decodeWorldSpriteAssetBytes,
   decompressGzip,
   type FileSource,
   type LoadedCurrentProjectCore,
   loadAllAuthorScenes,
   loadCurrentProjectFrom,
   loadProjectMapById,
   loadStampTemplates,
   parseSpriteChunkStrict,
   withStableProjectRead,
 } from '@type-pal/reforge/author-io'
 import type { AuthorDiskBaseline } from './author-disk-baseline.js'
 import {
   type AuthorSaveInput,
   commitAuthorSave,
   prepareAuthorSave,
   recoverOwnAuthorSave,
 } from './author-save-journal.js'
 import {
   assertBattleSimulatorPathAvailable,
   BATTLE_SIMULATOR_PATH,
   type BattleSimulatorLibrary,
   isBattleSimulatorEmpty,
   loadBattleSimulatorLibrary,
   parseBattleSimulatorLibrary,
 } from './battle-simulator-library.js'
 import { binarySnapshotSignature, sha256Hex } from './binary-signature.js'
 import type { EditorState } from './edit-session.js'
 import { assertProjectSaveValid } from './project-diagnostics.js'
 import { isWorkspaceIdentityPath, type WorkspaceContext } from './workspace-context.js'
 import {
   type AuthorizedWorkspaceInput,
   authorizedDirectory,
   authorizedSaveScope,
   planAuthorizedWorkspacePaths,
   withAuthorizedWorkspaceMutation,
 } from './workspace-persistence.js'

 type EditorSourceProject = LoadedCurrentProjectCore

 /**
  * 只读项目 → 可变工作副本。by-id Record 翻成数组(Object.values,保原数组序);
  * 数组/Record 直传；loader 派生的默认场景缓存与 assetBase 不进入 EditorState。
  * 参数取数据核 LoadedProjectCore(不需 IO source;运行期 LoadedProject 是其子类型,照传)。
  */
 export function toEditorState(
   project: EditorSourceProject,
   scenes: SceneDef[] | RuntimeSceneDef[] | AuthorSceneDef[],
   projectMaps: Record<string, ProjectMap> = {}, // 键 = 稳定 map id；缺席 = 尚未按需加载
   scriptChunks: Record<string, ScriptChunkV1> = {},
   stamps?: StampTemplate[],
   battleSimulator?: BattleSimulatorLibrary,
 ): EditorState {
   if (project.manifest.content.stamps && stamps === undefined)
     throw new Error('toEditorState: manifest.content.stamps 已登记但调用方未加载图章模板表')
   return {
     // M2a-2:场景懒加载后 LoadedProject 不再带全量 → 编辑器 loadAllScenes 拉齐后传入
     scenes: scenes as SceneDef[],
     sceneIndex: structuredClone(project.sceneIndex),
     assetCatalog: structuredClone(project.assetCatalog),
     assetBlobs: {},
     maps: projectMaps,
     mapIndex: project.mapIndex,
     // W7B:tileset 注册表(loader 已 guard;缺省空)+ 上传字节暂存(载入时空,只存新上传)
     tilesets: project.tilesets,
     stamps: stamps ?? [],
     worldVariables: validateWorldVariableRegistryV1(structuredClone(project.worldVariables)),
     tilesetBlobs: {},
     scriptIndex: undefined,
     scriptChunks,
     migrationDiagnostics: structuredClone(project.migrationDiagnostics),
     sharedScripts: structuredClone(
       project.authorContent.sharedScripts,
     ) as unknown as EditorState['sharedScripts'],
     // by-id Record → 数组(Object.values 保序:indexById 按原数组序插入)
     actors: Object.values(project.actorsById),
     skills: Object.values(project.skills),
     items: project.authorContent.items as EditorState['items'],
     sprites: Object.values(project.spritesById),
     battleSprites: Object.values(project.battleSpritesById),
     // M4c-3:敌人/敌队(by-id → 数组)
     enemies: project.authorContent.enemies as EditorState['enemies'],
     enemyTeams: Object.values(project.enemyTeamsById),
     // D24:战场表(数组直传;缺 = 空)
     battleFields: project.battleFields,
     // B10:毒表(loader 原序数组直传;⚠ 勿用 poisonsById 转 —— 数值键升序重排破坏 round-trip)
     poisons: project.poisons,
     // W6:氛围表(数组直传;缺 = 空)
     ambiences: project.ambiences,
     // 商店表(数组直传;缺 = 空)
     shops: project.shops,
     // Record(非 by-id):直传
     levelUp: project.levelUp,
     locale: project.locale,
     // manifest 透传；启动入口及其开局世界只在 manifest.entryPoints 中保留一份真值。
     manifest: project.manifest,
     ...(battleSimulator ? { battleSimulator: parseBattleSimulatorLibrary(battleSimulator) } : {}),
   }
 }

 export interface ProjectWriteResult {
   snapshot: Map<string, string>
   cleanupWarning?: string
 }

 /** First-save inputs are read sequentially into the same journal as the author overrides. */
 export interface ProjectCopyInput {
   path: string
   read: () => Promise<Blob>
 }
 const interruptedSnapshots = new WeakMap<WorkspaceContext, Map<string, string>>()

 /** Before a new click is serialized, finish ONLY this page's original save and adopt its exact output diff. */
 export async function resumeOwnProjectSave(
   workspace: WorkspaceContext,
   dir: FileSystemDirectoryHandle,
   baseline: AuthorDiskBaseline,
   onRecovering?: () => void,
 ): Promise<ProjectWriteResult | null> {
   if (interruptedSnapshots.has(workspace)) onRecovering?.()
   const result = await recoverOwnAuthorSave(workspace, dir, baseline)
   const snapshot = interruptedSnapshots.get(workspace)
   interruptedSnapshots.delete(workspace)
   if (!result) return null
   if (!snapshot) throw new Error('原页面的保存快照缺失，请重新打开已恢复的项目')
   return { snapshot, ...(result.cleanupWarning ? { cleanupWarning: result.cleanupWarning } : {}) }
 }

 async function validatePreparedProject(
   source: FileSource,
   previousCatalog?: AssetCatalogV1,
 ): Promise<void> {
   await validateAuthorProjectContents(source, previousCatalog)
 }

 export interface AuthorProjectCheckReport {
   projectId: string
   scenes: number
   maps: number
   assets: number
 }

 /** Read-only admission covers the complete audit, not just the initial current-project load. */
 export async function checkAuthorProject(source: FileSource): Promise<AuthorProjectCheckReport> {
   return withStableProjectRead(source, () => validateAuthorProjectContents(source, undefined, true))
 }

 /** One validation kernel for author-save staging and the standalone author audit. */
 async function validateAuthorProjectContents(
   source: FileSource,
   previousCatalog?: AssetCatalogV1,
   auditMaps = false,
 ): Promise<AuthorProjectCheckReport> {
   const project = await loadCurrentProjectFrom(source)
   assertBattleSimulatorPathAvailable(project)
   const [scenes, stamps, battleSimulator] = await Promise.all([
     loadAllAuthorScenes(project),
     loadStampTemplates(project),
     loadBattleSimulatorLibrary(source),
   ])
   await serializeProjectWithMapCopies(
     toEditorState(project, scenes, {}, {}, stamps, battleSimulator),
     source,
   )
   if (auditMaps) {
     const tilesets = new Set(project.tilesets.map((tileset) => tileset.id))
     // Save copy-through deliberately does not parse maps. Audit each indexed map with the
     // current loader sequentially, without retaining the complete map set in editor state.
     for (const asset of project.mapIndex.maps) {
       const map = await loadProjectMapById(project, asset.id)
       for (const id of map.tilesetRefs)
         if (!tilesets.has(id)) throw new Error(`地图 ${asset.id} 引用不存在的瓦片集：${id}`)
     }
   }
   const checked = new Set<string>()
   for (const [id, record] of Object.entries(project.assetCatalog.assets)) {
     if (
       checked.has(record.path) ||
       JSON.stringify(previousCatalog?.assets[id]) === JSON.stringify(record)
     )
       continue
     checked.add(record.path)
     let bytes: ArrayBuffer
     try {
       bytes = await source.readBytes(record.path)
     } catch (cause) {
       throw new Error(`保存目标资源缺失或不可读：${record.path}`, { cause })
     }
     // Stream one changed resource at a time through the SAME bytes/hash/format preflight.
     await preflightProjectWriteSet({
       'manifest.json': project.manifest,
       [project.manifest.assets.catalog]: project.assetCatalog,
       [record.path]: bytes,
     })
   }
   return {
     projectId: project.manifest.id,
     scenes: scenes.length,
     maps: project.mapIndex.maps.length,
     assets: Object.keys(project.assetCatalog.assets).length,
   }
 }

 /** manifest.content 的键 → 序列化时该文件存什么值。 */
 type ContentKey =
   | 'actors'
   | 'tilesets'
   | 'stamps'
   | 'skills'
   | 'items'
   | 'locale'
   | 'sprites'
   | 'battleSprites'
   | 'enemies'
   | 'enemyTeams'
   | 'battleFields'
   | 'poisons'
   | 'ambiences'
   | 'shops'
   | 'migrationDiagnostics'
   | 'worldVariables'

 /**
  * 工作副本 → {相对路径: JSON 值} 文件集。按 manifest.content 的路径键映射;
  * 外加 manifest.json(整体)。返回纯 JSON 值(可 JSON.stringify)。
  */
 export function serializeProject(
   state: EditorState,
   opts?: { mapCopies?: Readonly<Record<string, string>> },
 ): Record<string, unknown> {
   // canonical 入口不变式必须在任一路径落盘前 fail-loud。
   assertProjectSaveValid(state)
   assertBattleSimulatorPathAvailable(state)
   // Match the current loader: an obsolete author-script directory cannot be saved as a
   // seemingly valid project. Internal canonical preview chunks are not author output.
   if (state.manifest.content.scripts !== undefined)
     throw new Error('当前 manifest 禁止 content.scripts，请使用 sharedScripts')
   const files: Record<string, unknown> = {}
   const fileOwners = new Map<string, string>()
   const addFile = (rel: string, value: unknown, owner: string): void => {
     const previous = fileOwners.get(rel)
     if (previous)
       throw new Error(`serializeProject: 输出路径冲突 "${rel}"（${previous} / ${owner}）`)
     fileOwners.set(rel, owner)
     files[rel] = value
   }
   const content = state.manifest.content
   if (!content.worldVariables)
     throw new Error('serializeProject: 当前项目缺 manifest.content.worldVariables')
-  if (!content.stamps && state.stamps.length > 0)
+  if (false && !content.stamps && state.stamps.length > 0)
     throw new Error('serializeProject: 项目有图章模板但 manifest.content.stamps 未登记')

   // content20:SceneIndex 是唯一发现/名称/路径真值；正文必须先于 index 写出。
   const dir = (content.scenes ?? 'content/scenes/').replace(/\/?$/, '/')
   const sceneIndexPath = `${dir}index.json`
   const sceneIndex: SceneIndexV1 = validateSceneIndex(state.sceneIndex, sceneIndexPath)
   const scenesById = new Map(state.scenes.map((scene) => [scene.id, scene] as const))
   for (const asset of sceneIndex.scenes) {
     const scene = scenesById.get(asset.id)
     if (!scene) throw new Error(`serializeProject: SceneIndex 登记场景缺正文 "${asset.id}"`)
     if (scene.id !== asset.id)
       throw new Error(`serializeProject: 场景 index/id 不符 "${asset.id}" / "${scene.id}"`)
     addFile(asset.path, scene, `场景 ${asset.id}`)
   }
   const orphanScenes = state.scenes.filter(
     (scene) => !sceneIndex.scenes.some((asset) => asset.id === scene.id),
   )
   if (orphanScenes.length)
     throw new Error(
       `serializeProject: scenes 存在未登记正文: ${orphanScenes.map((scene) => scene.id).join(', ')}`,
     )
   addFile(sceneIndexPath, sceneIndex, '场景索引')
   const mapIndex = validateMapIndex(state.mapIndex)
   const mapIndexRel = content.maps
   if (mapIndexRel) {
     addFile(mapIndexRel, mapIndex, '地图索引')
     const indexedIds = new Set<string>()
     for (const asset of mapIndex.maps) {
       if (asset.path === mapIndexRel)
         throw new Error(`serializeProject: 地图资产 "${asset.id}" 覆盖 map index 文件`)
       indexedIds.add(asset.id)
       const map = state.maps[asset.id]
       if (map) addFile(asset.path, formatProjectMap(map), `地图 ${asset.id}`)
       else {
         const copy = opts?.mapCopies?.[asset.path]
         if (copy !== undefined) addFile(asset.path, copy, `地图 ${asset.id} copy-through`)
       }
     }
     const orphanIds = Object.keys(state.maps).filter((id) => !indexedIds.has(id))
     if (orphanIds.length)
       throw new Error(`serializeProject: maps 存在未登记资产: ${orphanIds.join(', ')}`)
   } else throw new Error('serializeProject: 项目缺 manifest.content.maps')
   // 上传字节:键即资产相对路径，交 writeProject 的完整保存计划统一处理。
   for (const [rel, buf] of Object.entries(state.tilesetBlobs))
     addFile(rel, buf, `瓦片集上传 ${rel}`)
   // 各 content 文件:按 manifest 声明的路径键映射到对应值。
   const byKey: Record<ContentKey, unknown> = {
     actors: state.actors,
     skills: { skills: state.skills, levelUp: state.levelUp },
     items: state.items,
     locale: state.locale,
     sprites: state.sprites,
     battleSprites: state.battleSprites,
     enemies: state.enemies ?? [],
     enemyTeams: state.enemyTeams ?? [],
     battleFields: state.battleFields ?? [],
     tilesets: state.tilesets ?? [],
     stamps: formatStampTemplates(state.stamps),
     poisons: state.poisons ?? [],
     ambiences: state.ambiences ?? [],
     shops: validateShops(state.shops ?? []),
     migrationDiagnostics: {
       version: 1,
       diagnostics: (state.migrationDiagnostics?.diagnostics ?? []).filter((diagnostic) => {
         const item = state.items.find((candidate) => candidate.id === diagnostic.target.objectId)
         return !item?.[diagnostic.target.capability]
       }),
     },
     worldVariables: validateWorldVariableRegistryV1(state.worldVariables ?? {}),
   }

   // 只产出 manifest.content 里**声明了路径**的文件(sprites 缺则不产出 sprites.json)。
   for (const key of Object.keys(byKey) as ContentKey[]) {
     const rel = content[key]
     if (rel !== undefined) addFile(rel, byKey[key], `内容表 ${key}`)
   }
   if (content.sharedScripts !== undefined) {
     if (!state.sharedScripts)
       throw new Error('serializeProject: manifest 声明 sharedScripts 但 state.sharedScripts 缺失')
     checkAuthorScriptLibrary(state.sharedScripts as unknown as AuthorScriptLibrary)
     addFile(content.sharedScripts, state.sharedScripts, '共享脚本')
   }

   for (const [rel, bytes] of Object.entries(state.assetBlobs)) {
     if (!Object.values(state.assetCatalog.assets).some((record) => record.path === rel))
       throw new Error(`serializeProject: pending 资源未登记 catalog: ${rel}`)
     addFile(rel, bytes, `资源二进制 ${rel}`)
   }
   addFile(state.manifest.assets.catalog, validateAssetCatalog(state.assetCatalog), '资源注册表')

   // manifest.json 整体还原；每个入口的完整开局世界都在 entryPoints 中。
   addFile('manifest.json', state.manifest, '项目清单')

   if (state.battleSimulator !== undefined) {
     const library = parseBattleSimulatorLibrary(state.battleSimulator)
     if (!isBattleSimulatorEmpty(library)) addFile(BATTLE_SIMULATOR_PATH, library, '战斗模拟器配置')
   }

   return files
 }

 /**
  * 序列化边界：已加载地图用当前工作副本，未加载地图从源文件按原文本复制。
  * copy-through 不 JSON.parse，因此不会为了保存把全部地图对象常驻内存。
  * 未修改素材由保存协调器的懒读取输入复制，不在这里全量物化。
  */
 export async function serializeProjectWithMapCopies(
   state: EditorState,
   source: FileSource,
 ): Promise<Record<string, unknown>> {
   const mapCopies: Record<string, string> = {}
   await Promise.all(
     state.mapIndex.maps.map(async (asset) => {
       if (!state.maps[asset.id]) mapCopies[asset.path] = await source.readText(asset.path)
     }),
   )
   return serializeProject(state, { mapCopies })
 }

 /** 序列化单文件为落盘字符串(与 writeProject 写盘同规格,便于快照比对)。字符串值原样。 */
 function serializeOne(value: unknown): string {
   return typeof value === 'string' ? value : `${JSON.stringify(value, null, 2)}\n`
 }

 /**
  * 增量-diff(纯核,可测):next 中内容与快照不同 → write;快照有而 next 无 → remove。
  * 快照 = Map<rel, 上次落盘签名>;二进制使用完整 `bin:<bytes>:<sha256>`，同长度替换也必须写盘。
  */
 export async function diffFiles(
   prev: Map<string, string>,
   next: Record<string, unknown>,
   computedSignatures?: Map<string, string>,
 ): Promise<{ write: string[]; remove: string[] }> {
   const write: string[] = []
   for (const [rel, value] of Object.entries(next)) {
     const cur =
       value instanceof ArrayBuffer ? await binarySnapshotSignature(value) : serializeOne(value)
     computedSignatures?.set(rel, cur)
     if (prev.get(rel) !== cur) write.push(rel)
   }
   const remove = [...prev.keys()].filter((rel) => !(rel in next))
   return { write, remove }
 }

 function assertWorkspaceIdentityPathWritable(rel: string): void {
   if (isWorkspaceIdentityPath(rel))
     throw new Error(`项目写入不能覆盖 workspace identity 旁车：${rel}`)
 }

 async function readTextFileIfPresent(
   dir: FileSystemDirectoryHandle,
   rel: string,
 ): Promise<string | undefined> {
   const segs = rel.split('/')
   const fileName = segs.pop()!
   let d = dir
   try {
     for (const seg of segs) d = await d.getDirectoryHandle(seg)
     const fh = await d.getFileHandle(fileName)
     return await (await fh.getFile()).text()
   } catch (error) {
     if (error instanceof DOMException && error.name === 'NotFoundError') return undefined
     throw error
   }
 }

 function unionAssetCatalog(
   previous: AssetCatalogV1 | undefined,
   next: AssetCatalogV1,
 ): AssetCatalogV1 {
   if (!previous) return next
   return {
     version: 1,
     // 同 AssetId 更新时选 next；定义只引用稳定 AssetId，因此旧/新内容都能解析。
     // 被删除的旧 AssetId 暂留到内容 JSON 提交完成，再由 final catalog 收缩。
     assets: { ...previous.assets, ...next.assets },
   }
 }

 /**
  * FSA 落盘壳(增量 + 二进制):按 diffFiles 只写变化、删已删,返回新快照。
  * rel 逐段 getDirectoryHandle({create:true});二进制值(ArrayBuffer)写 Blob,其余序列化。
  * 无 prevSnapshot(首存)= 全写。真写留浏览器实测(需 FSA 授权 UI)。
  */
 export async function writeProject(
   target: AuthorizedWorkspaceInput,
   inputFiles: Record<string, unknown>,
   opts?: {
     prevSnapshot?: Map<string, string>
     removePaths?: readonly string[]
     onProgress?: (progress: { completed: number; total: number }) => void
     copies?: readonly ProjectCopyInput[]
     directories?: readonly string[]
     verifySource?: () => Promise<void>
     onStaged?: (bytes: number) => void
   },
 ): Promise<ProjectWriteResult> {
   // Freeze the click's output before the first asynchronous boundary. Staging must not read a
   // subsequently mutated working-copy object or upload buffer.
   const files = structuredClone(inputFiles)
   const verifySource = opts?.verifySource
   const removePaths = [...(opts?.removePaths ?? [])]
   const excluded = new Set(removePaths)
   const copyPaths = new Set<string>()
   const copies = (opts?.copies ?? [])
     .map(({ path, read }) => ({ path, read }))
     .filter((copy) => {
       assertWorkspaceIdentityPathWritable(copy.path)
       if (copyPaths.has(copy.path)) throw new Error(`复制清单路径重复：${copy.path}`)
       copyPaths.add(copy.path)
       return !(copy.path in files) && !excluded.has(copy.path)
     })
   const directories = [...(opts?.directories ?? [])]
   for (const path of directories) assertWorkspaceIdentityPathWritable(path)
   for (const rel of Object.keys(files)) assertWorkspaceIdentityPathWritable(rel)
   for (const rel of removePaths) assertWorkspaceIdentityPathWritable(rel)
   await preflightProjectWriteSet(files, removePaths)
   const rawManifest = files['manifest.json'] as { assets?: { catalog?: string } } | undefined
   const catalogPath = rawManifest?.assets?.catalog
   const prev = opts?.prevSnapshot
   const desiredSignatures = new Map<string, string>()
   const diff = prev
     ? await diffFiles(prev, files, desiredSignatures)
     : { write: Object.keys(files), remove: [] as string[] }
   const diffRemove = diff.remove
   for (const rel of diffRemove) assertWorkspaceIdentityPathWritable(rel)
   const retainedCopies = new Set(copies.map((copy) => copy.path))
   const remove = [...new Set([...diffRemove, ...removePaths])].filter(
     (rel) => !(rel in files) && !retainedCopies.has(rel),
   )
   const encoder = new TextEncoder()
   const byteLength = (value: unknown): number =>
     value instanceof ArrayBuffer ? value.byteLength : encoder.encode(serializeOne(value)).byteLength
   return withAuthorizedWorkspaceMutation(target, async (mutation) => {
     if ((copies.length || directories.length) && !authorizedSaveScope(mutation).firstSave)
       throw new Error('整笔复制只允许写入已授权的新项目目标')
     if ((copies.length || directories.length) && !verifySource)
       throw new Error('复制缺少来源复验，拒绝准备保存')
     // The raw directory handle is only exposed inside an active, single-use mutation session.
     // Reading the on-disk catalog stays under the same identity lock; the first destination write
     // performs one more verification immediately before it can create or remove anything.
     const dir = authorizedDirectory(mutation)
     const write = [...diff.write]
     let stagedCatalog: AssetCatalogV1 | undefined
     let finalCatalog: AssetCatalogV1 | undefined
     let previousCatalog: AssetCatalogV1 | undefined
     if (catalogPath && files[catalogPath]) {
       finalCatalog = validateAssetCatalog(files[catalogPath], catalogPath)
       const diskText = await readTextFileIfPresent(dir, catalogPath)
       const diskCatalog =
         diskText === undefined || diskText.trim() === ''
           ? undefined
           : validateAssetCatalog(JSON.parse(diskText) as unknown, `${catalogPath}（当前磁盘）`)
       previousCatalog = diskCatalog
       // close 中断后磁盘可能已经前滚，而内存快照仍是旧态。发现偏差时强制重写 catalog
       // 和内容，不能只相信 prevSnapshot 后误跳过用户的重试或撤销结果。
       if (diskCatalog && serializeOne(diskCatalog) !== serializeOne(finalCatalog)) {
         if (!write.includes(catalogPath)) write.push(catalogPath)
         for (const [rel, value] of Object.entries(files)) {
           if (
             !(value instanceof ArrayBuffer) &&
             rel !== catalogPath &&
             rel !== 'manifest.json' &&
             !write.includes(rel)
           )
             write.push(rel)
         }
       }
       if (write.includes(catalogPath)) stagedCatalog = unionAssetCatalog(diskCatalog, finalCatalog)
     }
     await planAuthorizedWorkspacePaths(
       mutation,
       [...write, ...remove, ...copies.map((copy) => copy.path)],
       catalogPath,
     )
     const sizes = new Map(write.map((rel) => [rel, byteLength(files[rel])]))
     const needsCatalogShrink =
       stagedCatalog !== undefined &&
       finalCatalog !== undefined &&
       serializeOne(stagedCatalog) !== serializeOne(finalCatalog)
     const stagedCatalogSize = needsCatalogShrink ? byteLength(stagedCatalog) : 0
     let total = [...sizes.values()].reduce((sum, size) => sum + size, stagedCatalogSize)
     let completed = 0
     // prev 在真实 IO 期间兼作落盘日志：未触及的旧条目仍代表真实文件，只在成功
     // close 后覆盖签名、成功/已不存在的 remove 后删条目。中断时同一 Map 因而是完整的实际磁盘快照。
     const rememberWrite = async (
       rel: string,
       value: unknown,
       signature = desiredSignatures.get(rel),
     ): Promise<void> => {
       if (!prev) return
       prev.set(
         rel,
         signature ??
           (value instanceof ArrayBuffer
             ? await binarySnapshotSignature(value)
             : serializeOne(value)),
       )
     }
     const advance = (size: number): void => {
       completed += size
       // 100% 只在删除也落定后报告；避免 manifest close 后、函数返回前 UI 先宣告完成。
       if (completed < total) opts?.onProgress?.({ completed, total })
     }
     const inputs: AuthorSaveInput[] = []
     const completions: Array<() => Promise<void>> = []
     for (const path of directories) inputs.push({ kind: 'mkdir', path })
     const addCopy = (copy: ProjectCopyInput) => {
       let copiedSize = 0
       inputs.push({
         kind: 'write',
         path: copy.path,
         read: async () => {
           const bytes = await copy.read()
           copiedSize = bytes.size
           total += copiedSize
           return bytes
         },
       })
       // Copies are unchanged source files, not editor-owned output. Keeping them in
       // the UI diff snapshot would falsely delete them on the next incremental save.
       completions.push(async () => {
         advance(copiedSize)
       })
     }
     const assetPaths = new Set(
       Object.values(finalCatalog?.assets ?? {}).map((record) => record.path),
     )
     for (const copy of copies.filter((copy) => assetPaths.has(copy.path))) addCopy(copy)
     const addWrite = (rel: string, value: unknown, size: number, signature?: string) => {
       const bytes = new Blob([value instanceof ArrayBuffer ? value : serializeOne(value)])
       inputs.push({ kind: 'write', path: rel, read: async () => bytes })
       completions.push(async () => {
         await rememberWrite(rel, value, signature)
         advance(size)
       })
     }
     for (const rel of write.filter((candidate) => files[candidate] instanceof ArrayBuffer))
       addWrite(rel, files[rel], sizes.get(rel) ?? 0)
     if (catalogPath && stagedCatalog) {
       addWrite(
         catalogPath,
         stagedCatalog,
         needsCatalogShrink ? stagedCatalogSize : (sizes.get(catalogPath) ?? 0),
         needsCatalogShrink ? serializeOne(stagedCatalog) : desiredSignatures.get(catalogPath),
       )
     }
     for (const copy of copies.filter((copy) => !assetPaths.has(copy.path))) addCopy(copy)
     for (const rel of write.filter(
       (candidate) =>
         !(files[candidate] instanceof ArrayBuffer) &&
         candidate !== catalogPath &&
         candidate !== 'manifest.json',
     )) {
       addWrite(rel, files[rel], sizes.get(rel) ?? 0)
     }
     // manifest 是最后一张引用表：旧 manifest 可能仍指向旧 catalog role 或旧 content path，
     // 因此 final catalog 收缩与物理删除都必须等新 manifest close 成功后再做。其后失败只会
     // 留下安全的 catalog 超集或孤儿文件，不会让任一已发布引用悬空。
     if (write.includes('manifest.json')) {
       addWrite('manifest.json', files['manifest.json'], sizes.get('manifest.json') ?? 0)
     }
     if (catalogPath && finalCatalog && needsCatalogShrink) {
       addWrite(catalogPath, finalCatalog, sizes.get(catalogPath) ?? 0)
     }
     for (const rel of remove) {
       inputs.push({ kind: 'remove', path: rel })
       completions.push(async () => {
         prev?.delete(rel)
       })
     }
     const snapshot = new Map<string, string>()
     for (const [rel, value] of Object.entries(files)) {
       snapshot.set(
         rel,
         value instanceof ArrayBuffer ? await binarySnapshotSignature(value) : serializeOne(value),
       )
     }
     const scope = authorizedSaveScope(mutation)
     const workspace = scope.workspace
     const prepared = await prepareAuthorSave(
       mutation,
       inputs,
       (source) => validatePreparedProject(source, scope.firstSave ? undefined : previousCatalog),
       {
         catalogPath,
         beforeSeal: verifySource,
         onStaged: opts?.onStaged,
       },
     )
     interruptedSnapshots.set(workspace, new Map(snapshot))
     opts?.onProgress?.({ completed, total })
     let appliedIndex = 0
     const result = await commitAuthorSave(prepared, async (step) => {
       if (step.kind !== 'mkdir') await completions[appliedIndex++]!()
     })
     interruptedSnapshots.delete(workspace)
     opts?.onProgress?.({ completed: total, total })
     return { snapshot, ...(result.cleanupWarning ? { cleanupWarning: result.cleanupWarning } : {}) }
   })
 }

 /** 写目标前的纯预检；Save As 必须在复制源树前调用，避免坏 pending 污染目标。 */
 export async function preflightProjectWriteSet(
   files: Record<string, unknown>,
   removePaths: readonly string[] = [],
 ): Promise<void> {
   for (const rel of Object.keys(files)) assertWorkspaceIdentityPathWritable(rel)
   for (const rel of removePaths) assertWorkspaceIdentityPathWritable(rel)
   if (Object.hasOwn(files, BATTLE_SIMULATOR_PATH)) {
     const value = files[BATTLE_SIMULATOR_PATH]
     parseBattleSimulatorLibrary(typeof value === 'string' ? JSON.parse(value) : value)
   }
   const rawManifest = files['manifest.json'] as { assets?: { catalog?: string } } | undefined
   const catalogPath = rawManifest?.assets?.catalog
   if (catalogPath && files[catalogPath]) {
     const catalog = validateAssetCatalog(files[catalogPath])
     for (const rel of removePaths) {
       if (!(rel in files) && Object.values(catalog.assets).some((record) => record.path === rel))
         throw new Error(`保存不能删除当前 catalog 仍引用的资源：${rel}`)
     }
     const recordsByPath = new Map<string, (typeof catalog.assets)[string][]>()
     for (const record of Object.values(catalog.assets))
       recordsByPath.set(record.path, [...(recordsByPath.get(record.path) ?? []), record])
     for (const [rel, value] of Object.entries(files)) {
       if (!(value instanceof ArrayBuffer)) continue
       const records = recordsByPath.get(rel)
       if (!records) continue // 非 catalog 管理的项目附属二进制不参与资源记录校验。
       const hash = await sha256Hex(value)
       for (const record of records)
         if (record.bytes !== value.byteLength || record.sha256 !== hash)
           throw new Error(`资源二进制与 catalog 不符: ${rel}`)
       if (records.some((record) => record.kind === 'tileset')) {
         const bytes = new Uint8Array(value)
         if (bytes[0] !== 0x1f || bytes[1] !== 0x8b)
           throw new Error(`瓦片集资源不是 canonical gzip: ${rel}`)
         try {
           parseSpriteChunkStrict(await decompressGzip(new Blob([value])))
         } catch (cause) {
           throw new Error(
             `瓦片集资源 RLE 损坏: ${rel}(${cause instanceof Error ? cause.message : String(cause)})`,
           )
         }
       }
       for (const record of records)
         if (record.kind === 'sprite') {
           try {
             await decodeWorldSpriteAssetBytes(record, value, `精灵资源 ${rel}`)
           } catch (cause) {
             throw new Error(
               `精灵资源 RLE 损坏: ${rel}(${cause instanceof Error ? cause.message : String(cause)})`,
             )
           }
         }
       for (const record of records)
         if (record.kind === 'battle-sprite') {
           try {
             await decodeBattleSpriteAssetBytes(record, value, `战斗精灵资源 ${rel}`)
           } catch (cause) {
             throw new Error(
               `战斗精灵资源 RLE 损坏: ${rel}(${cause instanceof Error ? cause.message : String(cause)})`,
             )
           }
         }
     }
   }
 }

