 /**
  * 工作副本 → {相对路径: JSON 值} 文件集。按 manifest.content 的路径键映射;
  * 外加 manifest.json(整体)。返回纯 JSON 值(可 JSON.stringify)。
  */
 export function serializeProject(
   state: EditorState,
   opts?: { mapCopies?: Readonly<Record<string, string>> },
 ): Record<string, unknown> {
   // canonical 入口不变式必须在任一路径落盘前 fail-loud。
   assertProjectSaveValid(state)
   assertBattleSimulatorPathAvailable(state)
   // Match the current loader: an obsolete author-script directory cannot be saved as a
   // seemingly valid project. Internal canonical preview chunks are not author output.
   if (state.manifest.content.scripts !== undefined)
     throw new Error('当前 manifest 禁止 content.scripts，请使用 sharedScripts')
   const files: Record<string, unknown> = {}
   const fileOwners = new Map<string, string>()
   const addFile = (rel: string, value: unknown, owner: string): void => {
     const previous = fileOwners.get(rel)
     if (previous)
       throw new Error(`serializeProject: 输出路径冲突 "${rel}"（${previous} / ${owner}）`)
     fileOwners.set(rel, owner)
     files[rel] = value
   }
   const content = state.manifest.content
   if (!content.worldVariables)
     throw new Error('serializeProject: 当前项目缺 manifest.content.worldVariables')
   if (!content.stamps && state.stamps.length > 0)
     throw new Error('serializeProject: 项目有图章模板但 manifest.content.stamps 未登记')

   // content20:SceneIndex 是唯一发现/名称/路径真值；正文必须先于 index 写出。
   const dir = (content.scenes ?? 'content/scenes/').replace(/\/?$/, '/')
   const sceneIndexPath = `${dir}index.json`
   const sceneIndex: SceneIndexV1 = validateSceneIndex(state.sceneIndex, sceneIndexPath)
   const scenesById = new Map(state.scenes.map((scene) => [scene.id, scene] as const))
   for (const asset of sceneIndex.scenes) {
     const scene = scenesById.get(asset.id)
     if (!scene) throw new Error(`serializeProject: SceneIndex 登记场景缺正文 "${asset.id}"`)
     if (scene.id !== asset.id)
       throw new Error(`serializeProject: 场景 index/id 不符 "${asset.id}" / "${scene.id}"`)
     addFile(asset.path, scene, `场景 ${asset.id}`)
   }
   const orphanScenes = state.scenes.filter(
     (scene) => !sceneIndex.scenes.some((asset) => asset.id === scene.id),
   )
   if (orphanScenes.length)
     throw new Error(
       `serializeProject: scenes 存在未登记正文: ${orphanScenes.map((scene) => scene.id).join(', ')}`,
     )
   addFile(sceneIndexPath, sceneIndex, '场景索引')
   const mapIndex = validateMapIndex(state.mapIndex)
   const mapIndexRel = content.maps
   if (mapIndexRel) {
     addFile(mapIndexRel, mapIndex, '地图索引')
     const indexedIds = new Set<string>()
     for (const asset of mapIndex.maps) {
       if (asset.path === mapIndexRel)
         throw new Error(`serializeProject: 地图资产 "${asset.id}" 覆盖 map index 文件`)
       indexedIds.add(asset.id)
       const map = state.maps[asset.id]
       if (map) addFile(asset.path, formatProjectMap(map), `地图 ${asset.id}`)
       else {
         const copy = opts?.mapCopies?.[asset.path]
         if (copy !== undefined) addFile(asset.path, copy, `地图 ${asset.id} copy-through`)
       }
     }
     const orphanIds = Object.keys(state.maps).filter((id) => !indexedIds.has(id))
     if (orphanIds.length)
       throw new Error(`serializeProject: maps 存在未登记资产: ${orphanIds.join(', ')}`)
   } else throw new Error('serializeProject: 项目缺 manifest.content.maps')
